package com.bank.interrupt.worker;

import com.bank.interrupt.model.Trade;

import java.util.concurrent.BlockingQueue;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// A worker that spends most of its time BLOCKED on queue.take().
// It stops cleanly when interrupted, because take() throws InterruptedException.
public class SettlementWorker implements Runnable {
    private static final Logger log = Logger.getLogger(SettlementWorker.class.getName());
    private final BlockingQueue<Trade> queue;
    private final AtomicInteger settled = new AtomicInteger();

    public SettlementWorker(BlockingQueue<Trade> queue) { this.queue = queue; }

    @Override
    public void run() {
        log.info("SettlementWorker started");
        try {
            // Loop condition ALSO checks the flag so we exit even between takes.
            while (!Thread.currentThread().isInterrupted()) {
                Trade trade = queue.take();        // BLOCKS; throws on interrupt
                settle(trade);
            }
        } catch (InterruptedException e) {
            // Interrupted while blocked: this IS our stop signal.
            Thread.currentThread().interrupt();     // restore the flag for callers
            log.info("SettlementWorker interrupted while waiting — shutting down cleanly");
        }
        log.info(() -> "SettlementWorker stopped. Settled=" + settled.get());
    }

    private void settle(Trade t) {
        // ... real code debits/credits with BigDecimal inside a transaction ...
        settled.incrementAndGet();
        log.fine(() -> "Settled " + t.getTradeId() + " amount " + t.getAmount());
    }

    public int settledCount() { return settled.get(); }
}
