package com.bank.interrupt.worker;

import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

// A worker doing PURE CPU work with no blocking call. An interrupt will not
// throw anything, so it must POLL isInterrupted() at safe checkpoints.
public class ReconciliationWorker implements Runnable {
    private static final Logger log = Logger.getLogger(ReconciliationWorker.class.getName());
    private final AtomicLong processed = new AtomicLong();

    @Override
    public void run() {
        log.info("ReconciliationWorker started");
        long batch = 0;
        // Poll the flag between batches — the cooperative checkpoint.
        while (!Thread.currentThread().isInterrupted()) {
            crunch();                    // one batch of CPU work
            processed.incrementAndGet();
            batch++;
            if (batch % 1000 == 0) {
                log.fine("Reconciled " + batch + " batches so far");
            }
        }
        log.info(() -> "ReconciliationWorker stopped at batch " + processed.get()
                + " (saw interrupt flag)");
    }

    private void crunch() {
        long end = System.nanoTime() + 200_000L; // ~0.2ms CPU work
        long x = 0;
        while (System.nanoTime() < end) x++;
    }

    public long processedCount() { return processed.get(); }
}
