package com.bank.interrupt.flag;

import java.util.logging.Logger;

// Demonstrates the crucial difference:
//   isInterrupted() -> reads the flag, leaves it set
//   Thread.interrupted() (static) -> reads the flag AND clears it
public class FlagDemo {
    private static final Logger log = Logger.getLogger(FlagDemo.class.getName());

    public void showIsInterruptedKeepsFlag() {
        Thread.currentThread().interrupt();                 // raise the flag
        boolean first  = Thread.currentThread().isInterrupted();
        boolean second = Thread.currentThread().isInterrupted();
        log.info(() -> "isInterrupted read twice -> " + first + ", " + second
                + " (flag STAYS set)");
        Thread.interrupted(); // clear so we don't leak the flag out of this demo
    }

    public void showStaticInterruptedClearsFlag() {
        Thread.currentThread().interrupt();                 // raise the flag
        boolean first  = Thread.interrupted();               // reads AND clears
        boolean second = Thread.interrupted();               // now false
        log.info(() -> "static interrupted() read twice -> " + first + ", " + second
                + " (flag was CLEARED by the first read)");
    }

    // The restore pattern: never swallow InterruptedException silently.
    public void restorePatternAfterBlockingCall() {
        try {
            Thread.sleep(50);
            throw new InterruptedException("simulated interrupt during blocking call");
        } catch (InterruptedException e) {
            // sleep/throw CLEARED the flag; restore it so callers still see cancellation.
            Thread.currentThread().interrupt();
            log.warning("caught InterruptedException, restored flag="
                    + Thread.currentThread().isInterrupted());
            Thread.interrupted(); // cleanup for the demo only
        }
    }
}
