package com.bank.interrupt;

import com.bank.interrupt.flag.FlagDemo;
import com.bank.interrupt.model.Trade;
import com.bank.interrupt.worker.ReconciliationWorker;
import com.bank.interrupt.worker.SettlementWorker;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.logging.*;

public class InterruptionDemo {
    private static final Logger log = Logger.getLogger(InterruptionDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new InterruptLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        FlagDemo flags = new FlagDemo();
        flags.showIsInterruptedKeepsFlag();
        flags.showStaticInterruptedClearsFlag();
        flags.restorePatternAfterBlockingCall();

        // Worker blocked on a queue — interrupt wakes it from take().
        BlockingQueue<Trade> queue = new LinkedBlockingQueue<>();
        SettlementWorker sw = new SettlementWorker(queue);
        Thread settleThread = new Thread(sw, "settle-pool-thread-1");
        settleThread.start();
        queue.put(new Trade("TRD-1", new BigDecimal("50000")));
        queue.put(new Trade("TRD-2", new BigDecimal("75000")));
        Thread.sleep(100);
        log.info("Requesting settlement worker to stop (interrupt)");
        settleThread.interrupt();          // polite request
        settleThread.join(2000);

        // CPU worker — must poll the flag because nothing throws.
        ReconciliationWorker rw = new ReconciliationWorker();
        Thread reconThread = new Thread(rw, "recon-pool-thread-1");
        reconThread.start();
        Thread.sleep(50);
        log.info("Requesting reconciliation worker to stop (interrupt)");
        reconThread.interrupt();
        reconThread.join(2000);

        log.info(() -> "DONE settled=" + sw.settledCount()
                + " reconciled=" + rw.processedCount());
    }
}

// ─── Would be in InterruptLogFormatter.java in a real project ───
class InterruptLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
