package com.bank.interrupt;

import com.bank.interrupt.model.Trade;
import com.bank.interrupt.worker.ReconciliationWorker;
import com.bank.interrupt.worker.SettlementWorker;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.util.concurrent.*;

import static org.junit.jupiter.api.Assertions.*;

class InterruptionTest {

    @Test
    void isInterruptedDoesNotClearFlag() {
        Thread.currentThread().interrupt();
        assertTrue(Thread.currentThread().isInterrupted());
        assertTrue(Thread.currentThread().isInterrupted(), "flag must still be set");
        assertTrue(Thread.interrupted(), "static clears it once"); // cleanup
        assertFalse(Thread.currentThread().isInterrupted());
    }

    @Test
    void staticInterruptedClearsFlag() {
        Thread.currentThread().interrupt();
        assertTrue(Thread.interrupted(), "first read sees true");
        assertFalse(Thread.interrupted(), "second read sees false — it was cleared");
    }

    @Test
    void blockedWorkerStopsOnInterrupt() throws Exception {
        BlockingQueue<Trade> queue = new LinkedBlockingQueue<>();
        SettlementWorker sw = new SettlementWorker(queue);
        Thread t = new Thread(sw, "settle-pool-thread-1");
        t.start();
        queue.put(new Trade("TRD-1", new BigDecimal("50000")));
        Thread.sleep(100);
        t.interrupt();
        t.join(2000);
        assertFalse(t.isAlive(), "worker must exit cleanly after interrupt");
        assertEquals(1, sw.settledCount(), "the queued trade settled before stop");
    }

    @Test
    void cpuWorkerStopsByPollingFlag() throws Exception {
        ReconciliationWorker rw = new ReconciliationWorker();
        Thread t = new Thread(rw, "recon-pool-thread-1");
        t.start();
        Thread.sleep(50);
        t.interrupt();
        t.join(2000);
        assertFalse(t.isAlive(), "CPU worker must observe the flag and stop");
        assertTrue(rw.processedCount() > 0, "it did real work before stopping");
    }
}
